/* Minimal Warm — sand and clay neutrals, soft radii, quiet contrast */
.theme-minimal-warm {
  --bg: oklch(0.965 0.014 75);
  --surface: oklch(0.99 0.008 75);
  --surface-2: oklch(0.935 0.02 72);
  --fg: oklch(0.26 0.02 55);
  --fg-muted: oklch(0.52 0.025 55);
  --accent: oklch(0.6 0.11 45);
  --accent-fg: oklch(0.99 0.005 75);
  --accent-2: oklch(0.62 0.07 150);
  --line: oklch(0.26 0.02 55 / 14%);
  --success: oklch(0.62 0.11 150);
  --warning: oklch(0.75 0.12 80);
  --danger: oklch(0.58 0.16 28);

  --radius: 0.875rem;
  --radius-sm: 0.5rem;
  --radius-lg: 1.25rem;
  --radius-pill: 9999px;

  --shadow-1: 0 1px 2px 0 oklch(0.3 0.03 55 / 8%);
  --shadow-2: 0 10px 26px -14px oklch(0.3 0.03 55 / 30%);
  --shadow-3: 0 22px 50px -24px oklch(0.3 0.03 55 / 34%);
  --glow: 0 0 0 3px oklch(0.6 0.11 45 / 18%);

  --border-width: 1px;
  --blur-amount: 0px;

  --font-display: "Lora", Georgia, serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;

  --tracking-display: -0.02em;
  --label-transform: uppercase;
  --label-tracking: 0.14em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-minimal-warm h1,
.theme-minimal-warm h2,
.theme-minimal-warm h3 {
  font-family: var(--font-display);
  font-weight: 500;
  letter-spacing: var(--tracking-display);
}

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
